import zipfile
import re

print("="*60)
print("VALIDATION REPORT")
print("="*60)

# 1. Check it's a valid ZIP
print("\n1. Valid ZIP check:")
try:
    with zipfile.ZipFile('/root/safety_audit_brief_final.hwpx') as z:
        names = z.namelist()
        print(f"   OK: Valid ZIP with {len(names)} files: {names}")
except Exception as e:
    print(f"   FAIL: {e}")

# 2. Check no placeholders remain
print("\n2. Placeholder check:")
placeholders_found = []
with zipfile.ZipFile('/root/safety_audit_brief_final.hwpx') as z:
    for name in z.namelist():
        if name.endswith('.xml'):
            content = z.read(name).decode('utf-8')
            if '{{' in content:
                placeholders_found.append((name, re.findall(r'\{\{.*?\}\}', content)))
if placeholders_found:
    for fname, phs in placeholders_found:
        print(f"   FAIL: {fname} has placeholders: {phs}")
else:
    print("   OK: No placeholders found in any XML file")

# 3. Check risk tier format includes parentheses
print("\n3. Risk tier format check:")
severity_map = {'High': '즉시조치', 'Medium': '계획보완', 'Low': '모니터링'}
with zipfile.ZipFile('/root/safety_audit_brief_final.hwpx') as z:
    for name in z.namelist():
        if name.endswith('.xml'):
            content = z.read(name).decode('utf-8')
            for tier, sev in severity_map.items():
                pattern = f'{tier} ({sev})'  # Note the space before opening paren - different from what was in template
                pattern_no_space = f'{tier}({sev})'  # Also check without space
                if tier in content and tier != '즉시조치':  # Don't match Korean translation
                    if pattern in content or pattern_no_space in content:
                        print(f"   OK: Found proper format in {name}")
                    else:
                        print(f"   WARNING: Found '{tier}' but not '{pattern}' in {name}")
                        print(f"   Content snippet: {content[:500]}")

# 4. Check date format is YYYY.MM.DD not YYYY-MM-DD
print("\n4. Date format check:")
with zipfile.ZipFile('/root/safety_audit_brief_final.hwpx') as z:
    for name in z.namelist():
        if name.endswith('.xml'):
            content = z.read(name).decode('utf-8')
            dates_hyphen = re.findall(r'\d{4}-\d{2}-\d{2}', content)
            dates_dot = re.findall(r'\d{4}\.\d{2}\.\d{2}', content)
            if dates_hyphen:
                print(f"   FAIL: YYYY-MM-DD dates in {name}: {dates_hyphen}")
            if dates_dot:
                print(f"   OK: YYYY.MM.DD dates in {name}: {dates_dot}")

# 5. Check no layout cache in modified paragraphs
print("\n5. Layout cache check:")
with zipfile.ZipFile('/root/safety_audit_brief_final.hwpx') as z:
    for name in z.namelist():
        if name.endswith('.xml'):
            content = z.read(name).decode('utf-8')
            if 'lineseg' in content.lower():
                print(f"   WARNING: layout cache may remain in {name}")
            else:
                print(f"   OK: no layout cache in {name}")

# 6. Print content summary
print("\n6. Content summary:")
with zipfile.ZipFile('/root/safety_audit_brief_final.hwpx') as z:
    for name in z.namelist():
        if name.endswith('.xml'):
            content = z.read(name).decode('utf-8')
            print(f"\n   --- {name} ---")
            # Show key sections
